function applyTemplate(template) {
    STATE.currentTemplate = template;
    const page = document.getElementById('cvPage');
    page.className = 'page template-' + template;

    document.querySelectorAll('.template-card').forEach(c => {
        c.classList.toggle('active', c.dataset.template === template);
    });

    showToast(`Plantilla: ${template.charAt(0).toUpperCase() + template.slice(1)}`, 'info');
}

// ============================================
// COLOR TEMA
// ============================================
function changeThemeColor(element) {
    const color = element.dataset.color;
    STATE.themeColor = color;

    document.querySelectorAll('.color-swatch').forEach(s => s.classList.remove('active'));
    element.classList.add('active');

    // Aplicar color a elementos CSS variables
    document.documentElement.style.setProperty('--theme-color', color);

    // Actualizar estilos dinámicamente
    const style = document.createElement('style');
    style.id = 'dynamic-theme';
    const existing = document.getElementById('dynamic-theme');
    if (existing) existing.remove();

    style.innerHTML = `
        .cv-section-title { color: ${color} !important; border-color: ${color} !important; }
        .cv-name { color: ${color} !important; }
        .cv-header { border-bottom-color: ${color} !important; }
        .cv-skill { color: ${color} !important; border-color: ${color}40 !important; background: ${color}15 !important; }
        .section-title { color: ${color} !important; }
        .panel-btn { background: ${color} !important; }
        .panel-btn:hover { background: ${color}dd !important; }
        .panel-field input:focus, .panel-field textarea:focus, .panel-field select:focus { 
            border-color: ${color} !important; 
            box-shadow: 0 0 0 1px ${color} !important; 
        }
        .template-card.active { border-color: ${color} !important; background: ${color}15 !important; }
    `;
    document.head.appendChild(style);

    renderCV();
}

