    fields.forEach(fieldId => {
        const field = document.getElementById(fieldId);
        if (field && field.value.trim()) {
            field.value = enhanceString(field.value);
            improved++;
        }
    });

    STATE.experiences.forEach(exp => {
        if (exp.description) {
            exp.description = enhanceString(exp.description);
        }
    });

    renderExperienceList();
    renderCV();
    showToast(`✓ ${improved} campos mejorados`, 'success');
}

function expandText() {
    STATE.experiences.forEach(exp => {
        if (exp.description && exp.description.length < 150) {
            exp.description = expandDescription(exp.description);
        }
    });

    const profile = document.getElementById('profile');
    if (profile.value && profile.value.length < 200) {
        profile.value = expandDescription(profile.value);
    }

    renderExperienceList();
    renderCV();
    showToast('✓ Textos ampliados', 'success');
}

function organizeText() {
    // Ordena experiencias por fecha
    STATE.experiences.sort((a, b) => {
        if (!a.endDate) return -1;
        if (!b.endDate) return 1;
        return new Date(b.endDate) - new Date(a.endDate);
    });

    // Ordena educación por fecha
    STATE.educations.sort((a, b) => {
        if (!a.date) return 1;
        if (!b.date) return -1;
        return new Date(b.date) - new Date(a.date);
    });

    renderExperienceList();
    renderEducationList();
    renderCV();
    showToast('✓ Contenido ordenado cronológicamente', 'success');
}

function enhanceString(text) {
    if (!text) return '';

    const synonyms = {
        'hice': ['desarrollé', 'implementé', 'ejecuté', 'llevé a cabo'],
        'trabajé': ['colaboré', 'gestioné', 'dirigí', 'coordiné'],
        'ayudé': ['facilité', 'apoyé', 'asistí', 'contribuí a'],
        'usé': ['utilicé', 'dominé', 'empleé', 'apliqué'],
        'bueno': ['excelente', 'destacado', 'excepcional', 'sobresaliente'],
        'importante': ['significativo', 'relevante', 'clave', 'estratégico'],
        'mucho': ['considerablemente', 'significativamente', 'notablemente'],
        'cosas': ['elementos', 'aspectos', 'componentes', 'factores'],
        'trabajo': ['labor profesional', 'desempeño', 'contribución']
    };

    let result = text;
    Object.entries(synonyms).forEach(([word, options]) => {
        const regex = new RegExp('\\b' + word + '\\b', 'gi');
        if (regex.test(result)) {
            const replacement = options[Math.floor(Math.random() * options.length)];
            result = result.replace(regex, replacement);
        }
    });

    return result;
}

function expandDescription(text) {
    if (!text) return '';

    const connectors = [
        'Además, ',
        'Asimismo, ',
        'De forma complementaria, ',
        'En paralelo, ',
        'Como parte de mis responsabilidades, '
    ];

    const expansions = [
        'logrando resultados medibles y un impacto positivo en el equipo.',
        'contribuyendo al cumplimiento de los objetivos estratégicos de la organización.',
        'desarrollando competencias clave para el crecimiento profesional.',
        'optimizando procesos y mejorando la eficiencia operativa.',
        'colaborando con equipos multidisciplinarios para alcanzar metas comunes.'
    ];

    if (text.length < 100) {
        const connector = connectors[Math.floor(Math.random() * connectors.length)];
        const expansion = expansions[Math.floor(Math.random() * expansions.length)];
        return text + ' ' + connector.toLowerCase() + expansion;
    }

    return text;
}

function enhanceProfile() {
    const profile = document.getElementById('profile');
    if (!profile.value.trim()) {
        profile.value = 'Profesional con sólida trayectoria y compromiso con la excelencia. Especializado en aportar valor mediante soluciones innovadoras y trabajo en equipo. Orientado a resultados y con capacidad de adaptación a entornos dinámicos.';
    } else {
        profile.value = enhanceString(profile.value);
        profile.value = expandDescription(profile.value);
    }
    renderCV();
    showToast('✓ Perfil mejorado', 'success');
}

function enhanceExperience(id) {
    const exp = STATE.experiences.find(e => e.id === id);
    if (exp && exp.description) {
        exp.description = enhanceString(exp.description);
        exp.description = expandDescription(exp.description);
        renderExperienceList();
        renderCV();
        showToast('✓ Experiencia mejorada', 'success');
    }
}

// ============================================
// RENDER CV
// ============================================
function renderCV() {
    const doc = document.getElementById('cvDoc');
    const themeColor = STATE.themeColor;

    const fullName = document.getElementById('fullName').value || 'Tu Nombre Completo';
    const jobTitle = document.getElementById('jobTitle').value || 'Cargo Profesional';
    const email = document.getElementById('email').value;
    const phone = document.getElementById('phone').value;
    const location = document.getElementById('location').value;
    const linkedin = document.getElementById('linkedin').value;
    const profile = document.getElementById('profile').value || 'Añade un breve perfil profesional destacando tu experiencia y objetivos.';
    const skillsText = document.getElementById('skills').value;

    // Skills
    const skills = skillsText.split(',').map(s => s.trim()).filter(s => s.length > 0);
    const skillsHTML = skills.length > 0 
        ? skills.map(s => `<span class="cv-skill">${escapeHtml(s)}</span>`).join('')
        : '<span style="color:#8a8886;font-style:italic;">Añade tus habilidades</span>';

    // Experiencias
    const expHTML = STATE.experiences.filter(e => e.company || e.position).map(e => {
        const startStr = e.startDate ? formatDate(e.startDate) : '';
        const endStr = e.endDate ? formatDate(e.endDate) : 'Actualidad';
        const dates = startStr || endStr ? `${startStr} — ${endStr}` : '';
        return `
            <div class="cv-item">
                <div class="cv-item-head">
                    <div>
                        <span class="cv-item-title">${escapeHtml(e.position || 'Puesto')}</span>
                        <span class="cv-item-company"> | ${escapeHtml(e.company || 'Empresa')}</span>
                    </div>
                    <span class="cv-item-date">${escapeHtml(dates)}</span>
                </div>
                ${e.description ? `<div class="cv-item-desc">${formatDescription(e.description)}</div>` : ''}
            </div>
        `;
    }).join('') || '<p style="color:#8a8886;font-style:italic;">Sin experiencias registradas</p>';

    // Educación
    const eduHTML = STATE.educations.filter(e => e.degree || e.institution).map(e => {
        const dateStr = e.date ? formatDate(e.date) : '';
        return `
            <div class="cv-item">
                <div class="cv-item-head">
                    <div>
                        <span class="cv-item-title">${escapeHtml(e.degree || 'Título')}</span>
                        <span class="cv-item-company"> | ${escapeHtml(e.institution || 'Institución')}</span>
                    </div>
                    <span class="cv-item-date">${escapeHtml(dateStr)}</span>
                </div>
                ${e.description ? `<div class="cv-item-desc">${escapeHtml(e.description)}</div>` : ''}
            </div>
        `;
    }).join('') || '<p style="color:#8a8886;font-style:italic;">Sin formación registrada</p>';

    // Idiomas
    const langHTML = STATE.languages.filter(l => l.name).map(l => `
        <div class="cv-lang-item">
            <span>${escapeHtml(l.name)}</span>
            <span class="cv-lang-level">${escapeHtml(l.level)}</span>
        </div>
    `).join('') || '<p style="color:#8a8886;font-style:italic;">Sin idiomas registrados</p>';

    // Foto
    const photoHTML = STATE.photoData 
        ? `<img src="${STATE.photoData}" class="cv-photo" alt="Foto">`
        : `<div class="cv-photo-placeholder">📷<br>Sube tu foto</div>`;

    // Firma
    const signatureHTML = STATE.signatureData 
        ? `<img src="${STATE.signatureData}" alt="Firma">`
        : '<div style="height:45px;"></div>';

    // Contacto
    const contactItems = [];
    if (email) contactItems.push(`<span>📧 ${escapeHtml(email)}</span>`);
    if (phone) contactItems.push(`<span>📱 ${escapeHtml(phone)}</span>`);
    if (location) contactItems.push(`<span>📍 ${escapeHtml(location)}</span>`);
    if (linkedin) contactItems.push(`<span>🔗 ${escapeHtml(linkedin)}</span>`);

    // Hash certificación
    const hash = generateHash(fullName + Date.now());

    doc.innerHTML = `
        <div class="cv-header">
            <div class="cv-photo-container">${photoHTML}</div>
            <div class="cv-personal">
                <div class="cv-name">${escapeHtml(fullName)}</div>
                <div class="cv-role">${escapeHtml(jobTitle)}</div>
                <div class="cv-contact">${contactItems.join('')}</div>
            </div>
        </div>

        <div class="cv-section">
            <div class="cv-section-title">Perfil Profesional</div>
            <div class="cv-item-desc">${formatDescription(profile)}</div>
        </div>

        <div class="cv-section">
            <div class="cv-section-title">Experiencia Laboral</div>
            ${expHTML}
        </div>

        <div class="cv-section">
            <div class="cv-section-title">Formación Académica</div>
            ${eduHTML}
        </div>

        <div class="cv-section">
            <div class="cv-section-title">Habilidades</div>
            <div class="cv-skills-list">${skillsHTML}</div>
        </div>

        <div class="cv-section">
            <div class="cv-section-title">Idiomas</div>
            ${langHTML}
        </div>

        <div class="cv-footer">
            <div class="cv-signature">
                ${signatureHTML}
                <div class="cv-signature-line">${escapeHtml(fullName)}</div>
            </div>
            <div class="certification">
                <strong>✓ Certificadodigitalmente</strong><br>
                Belentani NOIACORE<br>
                Sistema CV Pro v2.0<br>
                <div class="cert-hash">ID: ${hash}</div>
            </div>
        </div>
    `;

    updateWordCount();
}

function formatDate(dateStr) {
    if (!dateStr) return '';
    const [year, month] = dateStr.split('-');
    const months = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
    return `${months[parseInt(month)-1]} ${year}`;
}

function formatDescription(text) {
    // Convertir líneas que empiezan con - o * en listas
    const lines = text.split('\n');
    const hasBullets = lines.some(l => l.trim().startsWith('-') || l.trim().startsWith('*'));

    if (hasBullets) {
        const items = lines
            .filter(l => l.trim())
            .map(l => `<li>${escapeHtml(l.replace(/^[\s\-\*]+/, ''))}</li>`)
            .join('');
        return `<ul>${items}</ul>`;
    }

    return escapeHtml(text).replace(/\n/g, '<br>');
}

function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function generateHash(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        const char = str.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash = hash & hash;
    }
    return 'BNC-' + Math.abs(hash).toString(16).toUpperCase().padStart(8, '0');
}

function updateWordCount() {
    const text = document.getElementById('cvDoc').innerText;
    const words = text.trim().split(/\s+/).filter(w => w.length > 0).length;
    document.getElementById('wordCount').textContent = `${words} palabras`;
}

// ============================================
// LIMITAR 1 PÁGINA
// ============================================
function limitTo1Page() {
    const page = document.getElementById('cvDoc');
    const pageHeight = 247; // mm aprox en A4 con márgenes

    // Reducir fuente gradualmente
    let currentSize = STATE.fontSize;
    while (currentSize > 9 && page.scrollHeight > 1050) {
        currentSize -= 0.5;
        page.style.fontSize = currentSize + 'pt';
    }

    // Si aún es muy grande, eliminar descripciones de experiencias más antiguas
    if (page.scrollHeight > 1050 && STATE.experiences.length > 2) {
        STATE.experiences.slice(2).forEach(e => e.description = '');
        renderExperienceList();
        renderCV();
    }

    STATE.fontSize = currentSize;
    document.getElementById('fontSize').value = Math.round(currentSize);
    showToast('✓ Ajustado a 1 página', 'success');
}

// ============================================
// GUARDAR/CARGAR
// ============================================
function saveToStorage(silent = false) {
    const data = {
        fullName: document.getElementById('fullName').value,
        jobTitle: document.getElementById('jobTitle').value,
        email: document.getElementById('email').value,
        phone: document.getElementById('phone').value,
        location: document.getElementById('location').value,
        linkedin: document.getElementById('linkedin').value,
        profile: document.getElementById('profile').value,
        skills: document.getElementById('skills').value,
        currentTemplate: STATE.currentTemplate,
        themeColor: STATE.themeColor,
        fontFamily: STATE.fontFamily,
        fontSize: STATE.fontSize,
        photoData: STATE.photoData,
        signatureData: STATE.signatureData,
        experiences: STATE.experiences,
        educations: STATE.educations,
        languages: STATE.languages,
        lastSaved: new Date().toISOString()
    };

    try {
        localStorage.setItem('belentani_cv_data', JSON.stringify(data));
        const time = new Date().toLocaleTimeString('es-ES', {hour:'2-digit', minute:'2-digit'});
        document.getElementById('lastSaved').textContent = `Último: ${time}`;
        document.getElementById('saveStatus').textContent = 'Guardado ✓';
        if (!silent) showToast('✓ Guardado correctamente', 'success');
    } catch(e) {
        showToast('⚠️ Error al guardar', 'error');
    }
}

function loadFromStorage() {
    try {
        const saved = localStorage.getItem('belentani_cv_data');
        if (!saved) return;

        const data = JSON.parse(saved);

        document.getElementById('fullName').value = data.fullName || '';
        document.getElementById('jobTitle').value = data.jobTitle || '';
        document.getElementById('email').value = data.email || '';
        document.getElementById('phone').value = data.phone || '';
        document.getElementById('location').value = data.location || '';
        document.getElementById('linkedin').value = data.linkedin || '';
        document.getElementById('profile').value = data.profile || '';
        document.getElementById('skills').value = data.skills || '';

        if (data.fontFamily) {
            STATE.fontFamily = data.fontFamily;
            document.getElementById('fontFamily').value = data.fontFamily;
        }
        if (data.fontSize) {
            STATE.fontSize = data.fontSize;
            document.getElementById('fontSize').value = data.fontSize;
        }

        if (data.photoData) STATE.photoData = data.photoData;
        if (data.signatureData) STATE.signatureData = data.signatureData;
        if (data.experiences && data.experiences.length > 0) STATE.experiences = data.experiences;
        if (data.educations && data.educations.length > 0) STATE.educations = data.educations;
        if (data.languages && data.languages.length > 0) STATE.languages = data.languages;

        if (data.currentTemplate) applyTemplate(data.currentTemplate);
        if (data.themeColor) {
            const swatch = document.querySelector(`.color-swatch[data-color="${data.themeColor}"]`);
            if (swatch) changeThemeColor(swatch);
        }

        renderExperienceList();
        renderEducationList();
        renderLanguagesList();

        if (data.lastSaved) {
            const d = new Date(data.lastSaved);
            document.getElementById('lastSaved').textContent = `Último: ${d.toLocaleTimeString('es-ES', {hour:'2-digit', minute:'2-digit'})}`;
        }

        showToast('✓ Datos cargados', 'info');
    } catch(e) {
        console.error('Error cargando:', e);
    }
}

function clearAllData() {
    if (!confirm('¿Borrar todos los datos del CV? Esta acción no se puede deshacer.')) return;

    localStorage.removeItem('belentani_cv_data');

    document.querySelectorAll('#sidePanel input, #sidePanel textarea').forEach(el => el.value = '');

    STATE.experiences = [];
    STATE.educations = [];
    STATE.languages = [];
    STATE.photoData = '';
    STATE.signatureData = '';

    clearSignature();

    addExperience();
    addEducation();
    addLanguage();

    renderCV();
    showToast('✓ Todos los datos eliminados', 'info');
}

// ============================================
// EXPORTACIÓN
// ============================================
function exportPDF() {
    const element = document.getElementById('cvPage');
    const fileName = (document.getElementById('fullName').value || 'CV') + '.pdf';

    showToast('⏳ Generando PDF...', 'info');

    const opt = {
        margin: 0,
        filename: fileName,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true, logging: false },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };

    html2pdf().set(opt).from(element).save().then(() => {
        showToast('✓ PDF exportado', 'success');
    }).catch(err => {
        showToast('⚠️ Error al generar PDF', 'error');
        console.error(err);
    });
}

function exportWord() {
    const element = document.getElementById('cvDoc');
    const fileName = (document.getElementById('fullName').value || 'CV') + '.doc';

    const styles = `
        <style>
            body { font-family: ${STATE.fontFamily}, sans-serif; }
            .cv-section-title { color: ${STATE.themeColor}; border-bottom: 2px solid ${STATE.themeColor}; font-weight:bold; text-transform:uppercase; font-size:13pt; padding-bottom:3px; margin-bottom:10px; }
            .cv-name { color: ${STATE.themeColor}; font-size:24pt; font-weight:bold; }
            .cv-role { font-size:13pt; color:#605e5c; margin-bottom:10px; }
            .cv-item-title { font-weight:bold; }
            .cv-skill { background:#e6eff7; padding:3px 8px; border-radius:10px; display:inline-block; margin:2px; }
            .cv-header { border-bottom: 3px solid ${STATE.themeColor}; padding-bottom:15px; margin-bottom:15px; }
        </style>
    `;

    const preHtml = `
        <html xmlns:o="urn:schemas-microsoft-com:office:office"
              xmlns:w="urn:schemas-microsoft-com:office:word"
              xmlns="http://www.w3.org/TR/REC-html40">
        <head><meta charset="utf-8"><title>CV</title>${styles}</head>
        <body>
    `;
    const postHtml = '</body></html>';
    const html = preHtml + element.innerHTML + postHtml;

    const blob = new Blob(['\ufeff', html], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    showToast('✓ Word exportado', 'success');
}

function printCV() {
    window.print();
}

// ============================================
// PANEL TOGGLE
// ============================================
function togglePanel() {
    STATE.panelOpen = !STATE.panelOpen;
    const panel = document.getElementById('sidePanel');
    const toggle = document.querySelector('.panel-toggle');

    if (STATE.panelOpen) {
        panel.classList.remove('hidden');
        toggle.style.right = '350px';
    } else {
        panel.classList.add('hidden');
        toggle.style.right = '10px';
    }
}

// ============================================
// NOTIFICACIONES
// ============================================
function showToast(message, type = 'success') {
    // Remover toast anterior si existe
    const existing = document.querySelector('.toast');
    if (existing) existing.remove();

    const toast = document.createElement('div');
    toast.className = `toast ${type}`;

    const icons = { success: '✅', error: '❌', info: 'ℹ️' };
    toast.innerHTML = `<span class="toast-icon">${icons[type] || '📌'}</span><span>${message}</span>`;

    document.body.appendChild(toast);

    setTimeout(() => {
        toast.style.opacity = '0';
        toast.style.transform = 'translateX(120%)';
        toast.style.transition = 'all 0.3s ease';
        setTimeout(() => toast.remove(), 300);
    }, 2500);
}

// ============================================
// OTROS
// ============================================
function updateDocTitle() {
    const name = document.getElementById('fullName').value || 'CV';
    document.getElementById('docTitle').value = `${name} - Microsoft Word`;
    document.title = `${name} - CV Maker Pro`;
}

function undoAction() {
    showToast('↶ Deshacer (Ctrl+Z)', 'info');
}

function redoAction() {
    showToast('↷ Rehacer (Ctrl+Y)', 'info');
}

// Atajos de teclado
document.addEventListener('keydown', (e) => {
    if (e.ctrlKey && e.key === 's') {
        e.preventDefault();
        saveToStorage();
    }
    if (e.ctrlKey && e.key === 'p') {
        e.preventDefault();
        printCV();
    }
});

// Aviso antes de cerrar
window.addEventListener('beforeunload', () => {
    saveToStorage(true);
});
</script>
</body>
</html>
```

