// ============================================
// CANVAS FIRMA
// ============================================
function initSignatureCanvas() {
    const canvas = document.getElementById('signatureCanvas');
    const ctx = canvas.getContext('2d');

    // Ajustar tamaño
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = 100;

    let drawing = false;
    let lastX = 0, lastY = 0;

    ctx.strokeStyle = '#000';
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    function getPos(e) {
        const r = canvas.getBoundingClientRect();
        const x = (e.touches ? e.touches[0].clientX : e.clientX) - r.left;
        const y = (e.touches ? e.touches[0].clientY : e.clientY) - r.top;
        return [x, y];
    }

    function start(e) {
        e.preventDefault();
        drawing = true;
        [lastX, lastY] = getPos(e);
    }

    function draw(e) {
        if (!drawing) return;
        e.preventDefault();
        const [x, y] = getPos(e);
        ctx.beginPath();
        ctx.moveTo(lastX, lastY);
        ctx.lineTo(x, y);
        ctx.stroke();
        [lastX, lastY] = [x, y];
    }

    function end() { drawing = false; }

    canvas.addEventListener('mousedown', start);
    canvas.addEventListener('mousemove', draw);
    canvas.addEventListener('mouseup', end);
    canvas.addEventListener('mouseout', end);
    canvas.addEventListener('touchstart', start, {passive: false});
    canvas.addEventListener('touchmove', draw, {passive: false});
    canvas.addEventListener('touchend', end);
}

function clearSignature() {
    const canvas = document.getElementById('signatureCanvas');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    STATE.signatureData = '';
    renderCV();
    showToast('Firma limpiada', 'info');
}

function saveSignature() {
    const canvas = document.getElementById('signatureCanvas');
    STATE.signatureData = canvas.toDataURL('image/png');
    renderCV();
    showToast('✓ Firma guardada', 'success');
}

function scrollToSignature() {
    document.getElementById('signatureSection').scrollIntoView({behavior: 'smooth', block: 'center'});
}

// ============================================
// FOTO
// ============================================
function handlePhotoUpload(event) {
    const file = event.target.files[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
        showToast('⚠️ El archivo debe ser una imagen', 'error');
        return;
    }

    if (file.size > 5 * 1024 * 1024) {
        showToast('⚠️ Imagen muy grande (máx 5MB)', 'error');
        return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
        STATE.photoData = e.target.result;
        renderCV();
        showToast('✓ Foto añadida', 'success');
    };
    reader.readAsDataURL(file);
}

