}

// ============================================
// MEJORA DE TEXTO CON IA LOCAL
// ============================================
function improveText() {
    const fields = ['fullName', 'jobTitle', 'profile'];
    let improved = 0;

    fields.forEach(fieldId => {
        const field = document.getElementById(fieldId);
        if (field && field.value.trim()) {
            field.value = enhanceString(field.value);
            improved++;
        }
    });

    STATE.experiences.forEach(exp => {
        if (exp.description) {
            exp.description = enhanceString(exp.description);
        }
    });

    renderExperienceList();
    renderCV();
    showToast(`✓ ${improved} campos mejorados`, 'success');
}

function expandText() {
    STATE.experiences.forEach(exp => {
        if (exp.description && exp.description.length < 150) {
            exp.description = expandDescription(exp.description);
        }
    });

    const profile = document.getElementById('profile');
    if (profile.value && profile.value.length < 200) {
        profile.value = expandDescription(profile.value);
    }

    renderExperienceList();
    renderCV();
    showToast('✓ Textos ampliados', 'success');
}

function organizeText() {
    // Ordena experiencias por fecha
    STATE.experiences.sort((a, b) => {
        if (!a.endDate) return -1;
        if (!b.endDate) return 1;
        return new Date(b.endDate) - new Date(a.endDate);
    });

    // Ordena educación por fecha
    STATE.educations.sort((a, b) => {
        if (!a.date) return 1;
        if (!b.date) return -1;
        return new Date(b.date) - new Date(a.date);
    });

    renderExperienceList();
    renderEducationList();
    renderCV();
    showToast('✓ Contenido ordenado cronológicamente', 'success');
}

function enhanceString(text) {
    if (!text) return '';

    const synonyms = {
        'hice': ['desarrollé', 'implementé', 'ejecuté', 'llevé a cabo'],
        'trabajé': ['colaboré', 'gestioné', 'dirigí', 'coordiné'],
        'ayudé': ['facilité', 'apoyé', 'asistí', 'contribuí a'],
        'usé': ['utilicé', 'dominé', 'empleé', 'apliqué'],
        'bueno': ['excelente', 'destacado', 'excepcional', 'sobresaliente'],
        'importante': ['significativo', 'relevante', 'clave', 'estratégico'],
        'mucho': ['considerablemente', 'significativamente', 'notablemente'],
        'cosas': ['elementos', 'aspectos', 'componentes', 'factores'],
        'trabajo': ['labor profesional', 'desempeño', 'contribución']
    };

    let result = text;
    Object.entries(synonyms).forEach(([word, options]) => {
        const regex = new RegExp('\\b' + word + '\\b', 'gi');
        if (regex.test(result)) {
            const replacement = options[Math.floor(Math.random() * options.length)];
            result = result.replace(regex, replacement);
        }
    });

    return result;
}

function expandDescription(text) {
    if (!text) return '';

    const connectors = [
        'Además, ',
        'Asimismo, ',
        'De forma complementaria, ',
        'En paralelo, ',
        'Como parte de mis responsabilidades, '
    ];

    const expansions = [
        'logrando resultados medibles y un impacto positivo en el equipo.',
        'contribuyendo al cumplimiento de los objetivos estratégicos de la organización.',
        'desarrollando competencias clave para el crecimiento profesional.',
        'optimizando procesos y mejorando la eficiencia operativa.',
        'colaborando con equipos multidisciplinarios para alcanzar metas comunes.'
    ];

    if (text.length < 100) {
        const connector = connectors[Math.floor(Math.random() * connectors.length)];
        const expansion = expansions[Math.floor(Math.random() * expansions.length)];
        return text + ' ' + connector.toLowerCase() + expansion;
    }

    return text;
}

function enhanceProfile() {
    const profile = document.getElementById('profile');
    if (!profile.value.trim()) {
        profile.value = 'Profesional con sólida trayectoria y compromiso con la excelencia. Especializado en aportar valor mediante soluciones innovadoras y trabajo en equipo. Orientado a resultados y con capacidad de adaptación a entornos dinámicos.';
    } else {
        profile.value = enhanceString(profile.value);
        profile.value = expandDescription(profile.value);
    }
    renderCV();
    showToast('✓ Perfil mejorado', 'success');
}

function enhanceExperience(id) {
    const exp = STATE.experiences.find(e => e.id === id);
    if (exp && exp.description) {
        exp.description = enhanceString(exp.description);
        exp.description = expandDescription(exp.description);
