function formatDate(dateStr) {
    if (!dateStr) return '';
    const [year, month] = dateStr.split('-');
    const months = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
    return `${months[parseInt(month)-1]} ${year}`;
}

function formatDescription(text) {
    // Convertir líneas que empiezan con - o * en listas
    const lines = text.split('\n');
    const hasBullets = lines.some(l => l.trim().startsWith('-') || l.trim().startsWith('*'));

    if (hasBullets) {
        const items = lines
            .filter(l => l.trim())
            .map(l => `<li>${escapeHtml(l.replace(/^[\s\-\*]+/, ''))}</li>`)
            .join('');
        return `<ul>${items}</ul>`;
    }

    return escapeHtml(text).replace(/\n/g, '<br>');
}

function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function generateHash(str) {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        const char = str.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash = hash & hash;
    }
    return 'BNC-' + Math.abs(hash).toString(16).toUpperCase().padStart(8, '0');
}

function updateWordCount() {
    const text = document.getElementById('cvDoc').innerText;
    const words = text.trim().split(/\s+/).filter(w => w.length > 0).length;
    document.getElementById('wordCount').textContent = `${words} palabras`;
}

