function exportPDF() {
    const element = document.getElementById('cvPage');
    const fileName = (document.getElementById('fullName').value || 'CV') + '.pdf';

    showToast('⏳ Generando PDF...', 'info');

    const opt = {
        margin: 0,
        filename: fileName,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true, logging: false },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };

    html2pdf().set(opt).from(element).save().then(() => {
        showToast('✓ PDF exportado', 'success');
    }).catch(err => {
        showToast('⚠️ Error al generar PDF', 'error');
        console.error(err);
    });
}

function exportWord() {
    const element = document.getElementById('cvDoc');
    const fileName = (document.getElementById('fullName').value || 'CV') + '.doc';

    const styles = `
        <style>
            body { font-family: ${STATE.fontFamily}, sans-serif; }
            .cv-section-title { color: ${STATE.themeColor}; border-bottom: 2px solid ${STATE.themeColor}; font-weight:bold; text-transform:uppercase; font-size:13pt; padding-bottom:3px; margin-bottom:10px; }
            .cv-name { color: ${STATE.themeColor}; font-size:24pt; font-weight:bold; }
            .cv-role { font-size:13pt; color:#605e5c; margin-bottom:10px; }
            .cv-item-title { font-weight:bold; }
            .cv-skill { background:#e6eff7; padding:3px 8px; border-radius:10px; display:inline-block; margin:2px; }
            .cv-header { border-bottom: 3px solid ${STATE.themeColor}; padding-bottom:15px; margin-bottom:15px; }
        </style>
    `;

    const preHtml = `
        <html xmlns:o="urn:schemas-microsoft-com:office:office"
              xmlns:w="urn:schemas-microsoft-com:office:word"
              xmlns="http://www.w3.org/TR/REC-html40">
        <head><meta charset="utf-8"><title>CV</title>${styles}</head>
        <body>
    `;
    const postHtml = '</body></html>';
    const html = preHtml + element.innerHTML + postHtml;

    const blob = new Blob(['\ufeff', html], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    showToast('✓ Word exportado', 'success');
}

